const express = require('express');
const nodemailer = require('nodemailer');
const crypto = require('crypto');

const app = express();
app.use(express.json());

// Multi-tenant configuration store
const tenantConfigs = new Map();

// Tenant registration with SMTP config
app.post('/api/tenants', async (req, res) => {
  const { tenantId, smtpHost, smtpPort, smtpUser, smtpPass, allowedDomains } = req.body;
  if (!tenantId || !smtpHost || !allowedDomains) {
    return res.status(400).json({ error: 'Missing required fields' });
  }
  if (!Array.isArray(allowedDomains) || !allowedDomains.every(d => typeof d === 'string')) {
    return res.status(400).json({ error: 'allowedDomains must be an array of strings' });
  }
  const apiKey = crypto.randomBytes(32).toString('hex');
  tenantConfigs.set(tenantId, {
    smtpHost,
    smtpPort: smtpPort || 587,
    smtpUser,
    smtpPass,
    allowedDomains: allowedDomains.map(d => d.toLowerCase()),
    apiKey
  });
  res.json({ apiKey });
});

// Authentication middleware
function authenticateTenant(req, res, next) {
  const authHeader = req.headers['x-api-key'];
  const tenantId = req.headers['x-tenant-id'];
  if (!authHeader || !tenantId) {
    return res.status(401).json({ error: 'Missing credentials' });
  }
  const config = tenantConfigs.get(tenantId);
  if (!config) {
    return res.status(401).json({ error: 'Unknown tenant' });
  }
  const providedKey = Buffer.from(String(authHeader));
  const expectedKey = Buffer.from(config.apiKey);
  // Guard against timingSafeEqual throwing on length mismatch
  if (
    providedKey.length !== expectedKey.length ||
    !crypto.timingSafeEqual(providedKey, expectedKey)
  ) {
    return res.status(401).json({ error: 'Invalid API key' });
  }
  req.tenantConfig = config;
  req.tenantId = tenantId;
  next();
}

// Domain validation for tenant isolation
function validateRecipientDomain(email, allowedDomains) {
  const domain = email.split('@').pop().toLowerCase();
  // allowedDomains is always a validated string array at this point
  if (!Array.isArray(allowedDomains)) {
    return false;
  }
  return allowedDomains.includes(domain);
}

// Email sending endpoint
app.post('/api/send', authenticateTenant, async (req, res) => {
  const { to, subject, body, from } = req.body;
  if (!to || !subject || !body) {
    return res.status(400).json({ error: 'Missing email fields' });
  }

  const recipients = Array.isArray(to) ? to : [to];

  // Validate all recipients against tenant's allowed domains
  for (const recipient of recipients) {
    if (typeof recipient !== 'string' || !recipient.includes('@')) {
      return res.status(400).json({ error: `Invalid email: ${recipient}` });
    }
    if (!validateRecipientDomain(recipient, req.tenantConfig.allowedDomains)) {
      return res.status(403).json({ 
        error: `Recipient domain not allowed for this tenant: ${recipient}` 
      });
    }
  }

  try {
    const transporter = nodemailer.createTransport({
      host: req.tenantConfig.smtpHost,
      port: req.tenantConfig.smtpPort,
      secure: req.tenantConfig.smtpPort === 465,
      auth: {
        user: req.tenantConfig.smtpUser,
        pass: req.tenantConfig.smtpPass
      }
    });

    const mailOptions = {
      from: from || req.tenantConfig.smtpUser,
      to: recipients.join(', '),
      subject,
      text: body
    };

    await transporter.sendMail(mailOptions);
    res.json({ success: true, recipients: recipients.length });
  } catch (err) {
    res.status(500).json({ error: 'Failed to send email' });
  }
});

module.exports = app;
